**ProjectileSpawner.cs**
```csharp
using UnityEngine;
using UnityEngine.Pool;

public class ProjectileSpawner : MonoBehaviour
{
    [SerializeField] private GameObject projectilePrefab;
    [SerializeField] private Transform muzzle;
    [SerializeField] private float fireRate = 0.2f;

    private IObjectPool<Projectile> pool;
    private float nextFireTime;

    void Awake()
    {
        pool = new ObjectPool<Projectile>(
            createFunc: () => Instantiate(projectilePrefab),
            actionOnGet: (p) => p.SetPool(pool),
            actionOnRelease: (p) => p.gameObject.SetActive(false),
            actionOnDestroy: (p) => Destroy(p.gameObject),
            defaultCapacity: 10
        );
    }

    void Update()
    {
        if (Input.GetButton("Fire") && Time.time >= nextFireTime)
        {
            var p = pool.Get();
            p.transform.position = muzzle.position;
            p.transform.rotation = muzzle.rotation;
            nextFireTime = Time.time + fireRate;
        }
    }
}
```

Make sure your Projectile prefab has a `Rigidbody` (set to "Is Kinematic" if you prefer manual movement) and a `Collider` to trigger the return to the pool. A common mistake is forgetting to set the `Rigidbody` velocity in `OnEnable`, which can cause projectiles to "freeze" in the air when reused!

That is a fantastic way to structure your AI; using a state-based approach for patrolling versus chasing makes the behavior feel much more natural!

Here is a clean script to get your enemy moving.

```csharp
using UnityEngine;
using UnityEngine.AI;
using System.Collections.Generic;

public class EnemyPatrol : MonoBehaviour
{
    public Transform[] waypoints;
    public float detectionRadius = 10f;
    public float chaseSpeed = 5f;
    public float patrolSpeed = 2f;
    public float loseSightTime = 3f;
    public LayerMask obstacleLayer;

    private NavMeshAgent agent;
    private Transform player;
    private int currentWaypointIndex = 0;
    private float lastSeenTime;
    private bool isChasing = false;

    void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        player = GameObject.FindWithTag("Player").transform;
        lastSeenTime = Time.time;
        if (waypoints.Length > 0) agent.SetDestination(waypoints[currentWaypointIndex].position);
    }

    void Update()
    {
        float distanceToPlayer = Vector3.Distance(transform.position, player.position);
        bool canSeePlayer = false;

        if (distanceToPlayer <= detectionRadius)
        {
            if (!Physics.Raycast(transform.position, (player.position - transform.position).normalized, out RaycastHit hit, detectionRadius, obstacleLayer))
            {
                if (hit.collider.CompareTag("Player")) canSeePlayer = true;
            }
        }

        if (canSeePlayer)
        {
            isChasing = true;
            lastSeenTime = Time.time;
            agent.speed = chaseSpeed;
            agent.SetDestination(player.position);
        }
        else if (Time.time - lastSeenTime > loseSightTime)
        {
            isChasing = false;
            agent.speed = patrolSpeed;
            if (!agent.pathPending && agent.remainingDistance < 0.5f)
            {
                currentWaypointIndex = (currentWaypointIndex + 1) % waypoints.Length;
                agent.SetDestination(waypoints[currentWaypointIndex].position);
            }
        }
    }
}
```

Make sure your "Player" object has the "Player" tag assigned in the Inspector, or the script won't be able to find it!

That is a fantastic set of mechanics to include; coyote time and jump buffering make a platformer feel significantly more polished and responsive! Here is a clean, production-ready script for your `CharacterBody2D`.

```gdscript
extends CharacterBody2D

@export_group("Movement")
@export var speed: float = 300.0
@export var acceleration: float = 1500.0
@export var friction: float = 1200.0

@export_group("Jump")
@export var jump_velocity: float = -400.0
@export var gravity_scale: float = 1.0
@export var jump_buffer_time: float = 0.1
@export var coyote_time: float = 0.15
@export var jump_cut_multiplier: float = 0.5

var jump_buffer_timer: float = 0.0
var coyote_timer: float = 0.0

func _physics_process(delta: float) -> void:
	# Add gravity
	if not is_on_floor():
		velocity.y += ProjectSettings.get_setting("physics/2d/default_gravity") * gravity_scale * delta
		coyote_timer -= delta
	else:
		coyote_timer = coyote_time

	# Handle Jump Buffer
	if Input.is_action_just_pressed("jump"):
		jump_buffer_timer = jump_buffer_time
	jump_buffer_timer -= delta

	# Handle Jump Execution
	if jump_buffer_timer > 0 and coyote_timer > 0:
		velocity.y = jump_velocity
		jump_buffer_timer = 0
		coyote_timer = 0

	# Handle Variable Jump Height (Jump Cut)
	if Input.is_action_just_released("jump") and velocity.y < 0:
		velocity.y *= jump_cut_multiplier

	# Movement logic
	var direction := Input.get_axis("move_left", "move_right")
	if direction != 0:
		velocity.x = move_toward(velocity.x, direction * speed, acceleration * delta)
	else:
		velocity.x = move_toward(velocity.x, 0, friction * delta)

	move_and_slide()
```

A common mistake is forgetting to reset the `coyote_timer` to 0 immediately after jumping; if you don't, the player might be able to "double jump" in mid-air.

