```

**CoinPickup.cpp**
```cpp
#include "CoinPickup.h"
#include "Components/SphereComponent.h"
#include "Components/StaticMeshComponent.h"
#include "GameFramework/PlayerState.h"
#include "Kismet/GameplayStatics.h"

ACoinPickup::ACoinPickup()
{
    PrimaryActorTick.bCanEverTick = true;

    CollisionComponent = CreateDefaultSubobject<USphereComponent>(TEXT("SphereComp"));
    RootComponent = CollisionComponent;

    MeshComponent = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("MeshComp"));
    MeshComponent->SetupAttachment(RootComponent);
}

void ACoinPickup::BeginPlay()
{
    Super::BeginPlay();
    CollisionComponent->OnComponentBeginOverlap.AddDynamic(this, &ACoinPickup::OnOverlapBegin);
}

void ACoinPickup::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);
    if (MeshComponent)
    {
        FRotator NewRotation = MeshComponent->GetActorRotation();
        MeshComponent->SetActorRotation(NewRotation + FRotator(0, RotationSpeed * DeltaTime, 0));
    }
}

void ACoinPickup::OnOverlapBegin(Uclass TArray<AActor*> OtherActors, AActor* OtherActor, VEC3 SweepRadius, bool bSweep, const FHitResult& SweepResult)
{
    if (bIsCollected || !GetOwnerRole().IsAuthority()) return;

    if (OtherActor && OtherActor->IsA(APawn::StaticClass()))
    {
        bIsCollected = true;
        APlayerState* PS = OtherActor->GetPlayerState();
        if (PS)
        {
            // Note: You must define a 'Score' variable in your custom PlayerState class
            // PS->Score += ScoreValue; 

            if (PickupSound) {
                UGameplayStatics::PlaySoundAtLocation(this, PickupSound, GetActorLocation());
            }
            Destroy();
        }
