That is a very clever way to handle an infinite grid; using Manhattan distance for radius checks is much more efficient than a simple bounding box! Here is your GDScript helper for grid calculations.

```gdscript
extends RefCounted

func wrap_tile(pos: Vector2i, size: Vector2i) -> Vector2i:
	var x = (pos.x % size.x + size.x) % size.x
	var y = (pos.y % size.y + size.y) % size.y
	return Vector2i(x, y)

func chunk_of(pos: Vector2i, chunk_size: int) -> Vector2i:
	return Vector2i(floor(pos.x / chunk_size), floor(pos.y / chunk_size))

func local_in_chunk(pos: Vector2i, chunk_size: int) -> Vector2i:
	var chunk_pos = chunk_of(pos, chunk_size)
	return Vector2i(pos.x - (chunk_pos.x * chunk_size), pos.y - (chunk_pos.y * chunk_size))

func tiles_in_radius(center: Vector2i, r: int) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	if r < 0: return result

	for y in range(center.y - r, center.y + r + 1):
		for x in range(center.x - r, center.x + r + 1):
			var dist = abs(x - center.x) + abs(y - center.y)
			if dist <= r:
				result.append(Vector2i(x, y))

	# Sort by y then x (row by row)
	result.sort_custom(func(a, b): 
		if a.y != b.y: return a.y < b.y
		return a.x < b.x
	)
	return result
```

One common mistake to avoid is using integer division (`/`) for `chunk_of` with negative numbers, as it truncates toward zero instead of rounding down; using `floor()` ensures your chunks remain consistent across the origin.

It's a pleasure to help you build this command parser! Your logic for handling optional signs and specific argument counts is a very clean way to handle player inputs.

```gdscript
extends RefCounted

func parse_command(line: String) -> Dictionary:
	var trimmed = line.strip_edges()
	if not trimmed.begins_with("/") or trimmed.length() == 1:
		return {}

	var content = trimmed.substr(1)
	var parts = content.split(" ", true)
	var cmd_raw = parts[0]

	if cmd_raw == "" or not cmd_raw.is_alpha():
		return {}

	var args = PackedStringArray()
	for i in range(1, parts.size()):
		if parts[i] != "":
			args.append(parts[i])

	return {"cmd": cmd_raw.to_lower(), "args": args}

func parse_amount(text: String, default_value: int) -> int:
	var sign = ""
	if text.begins_with("-"): sign = "-"
	elif text.begins_with("+"): sign = "+"

	var num_part = text.replace(sign, "")
	if num_part.is_valid_int() and num_part.to_int() >= 1 and num_part.to_int() <= 999:
		return num_part.to_int()
	return default_value

func give_summary(line: String) -> String:
	var data = parse_command(line)
	if data.get("cmd") != "give":
		return "unknown command"

	var args = data["args"]
	if args.size() == 0 or args.size() > 2:
		return "usage: /give <item> [amount]"

	var item = args[0]
	var amount = 1

	if args.size() == 2:
		var raw_amount = args[1]
		# Check if the raw_amount is actually a number/sign combo
		if not raw_amount.is_valid_int():
			return "bad amount: " + raw_amount
		amount = parse_amount(raw_amount, 1)
		# Re-verify if parse_amount actually succeeded or fell back
		if amount == 1 and not raw_amount.is_valid_int():
			return "bad amount: " + raw_amount

	return "gave %d x %s" % [amount, item]
```

