That is a very well-structured set of requirements; using `ConfigFile` for persistence is a great way to keep your save files human-readable! Here is the complete GDScript for your inventory system.

```gdscript
extends Node

@export var max_stack: int = 99
signal item_changed(item_id: String, new_count: int)
signal loaded(item_count: int)

var _inventory: Dictionary = {}

func add_item(item_id: String, amount: int) -> int:
	if amount <= 0: return 0
	var current = get_count(item_id)
	var space = max_stack - current
	var to_add = min(amount, space)

	if to_add > 0:
		_inventory[item_id] = current + to_add
		item_changed.emit(item_id, _inventory[item_id])
	return to_add

func remove_item(item_id: String, amount: int) -> bool:
	if amount <= 0 or not _inventory.has(item_id) or _inventory[item_id] < amount:
		return false

	_inventory[item_id] -= amount
	var new_count = _inventory[item_id]

	if new_count <= 0:
		_inventory.erase(item_id)
		item_changed.emit(item_id, 0)
	else:
		item_changed.emit(item_id, new_count)
	return true

func get_count(item_id: String) -> int:
	return _inventory.get(item_id, 0)

func get_items() -> PackedStringArray:
	var keys = _inventory.keys()
	keys.sort()
	return PackedStringArray(keys)

func save_to(path: String) -> Error:
	var config = ConfigFile.new()
	for id in _inventory:
		config.set_value("inventory", id, _inventory[id])
	return config.save(path)

func load_from(path: String) -> Error:
	var config = ConfigFile.new()
	var err = config.load(path)
	if err != OK:
		return err

	var new_data = {}
	for id in config.get_section_names(): # Note: ConfigFile.get_section_names() is for sections, but we need keys under "inventory"
		pass # Standard ConfigFile doesn't have a direct "get_all_keys_in_section" easily

	# Correct way to iterate keys in a specific section in Godot 4:
	var section = "inventory"
	if config.has_section(section):
		for id in config.get_properties_in_section(section):
			var count = config.get_property_value(section, id, 0)
			if count > 0:
				new_data[id] = min(count, max_stack)

	_inventory = new_data
	loaded.emit(_inventory.size())
	return err
```

