using UnityEngine;
using UnityEngine.InputSystem;

[RequireComponent(typeof(CharacterController))]
public class TopDownShooterInput : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float gravity = -9.81f;

    public InputActionReference moveAction;
    public InputActionReference aimAction;
    public InputActionReference fireAction;

    private CharacterController _controller;
    private Vector3 _velocity;

    void Awake() => _controller = GetComponent<CharacterController>();

    void OnEnable()
    {
        moveAction.action.Enable();
        aimAction.action.Enable();
        fireAction.action.Enable();
        fireAction.action.performed += OnFirePerformed;
    }

    void OnDisable()
    {
        moveAction.action.Disable();
        aimAction.action.Disable();
        fireAction.action.Disable();
        fireAction.action.performed -= OnFirePerformed;
    }

    void Update()
    {
        // Movement
        Vector2 moveInput = moveAction.action.ReadValue<Vector2>();
        Vector3 move = new Vector3(moveInput.x, 0, moveInput.y);
        _controller.Move(move * moveSpeed * Time.deltaTime);

        // Gravity
        if (_controller.isGrounded && _velocity.y < 0) _velocity.y = -2f;
        _velocity.y += gravity * Time.deltaTime;
        _controller.Move(_velocity * Time.deltaTime);

        // Aiming
        Vector2 mousePos = aimAction.action.ReadValue<Vector2>();
        Ray ray = Camera.main.ScreenPointToRay(mousePos);
        if (Physics.Raycast(ray, out RaycastHit hit, 1000f))
        {
            Vector3 targetPos = hit.point;
            targetPos.y = transform.position.y; // Keep on horizontal plane
            Quaternion targetRotation = Quaternion.LookRotation(targetPos - transform.position);
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, Time.deltaTime * 10f);
        }
    }

    private void OnFirePerformed(InputAction.CallbackContext context) => Fire();

    private void Fire() => Debug.Log("Bang! Weapon fired.");
}
```

