That is a very sophisticated request! I love how you're prioritizing performance by avoiding per-call allocations; it's a great way to keep your game running smoothly.

Here is the Unity 6 C# script using `Physics.OverlapSphereNonAlloc` and a simple line-of-sight check.

```csharp
using UnityEngine;
using System.Collections.Generic;

public interface IDamageable { void TakeDamage(float amount); }

public class Explosion : MonoBehaviour
{
    [Header("Settings")]
    public float radius = 5f;
    public float maxDamage = 50f;
    public float explosionForce = 500f;
    public float upwardsModifier = 2f;
    public LayerMask damageMask;
    public LayerMask obstacleMask;

    [Header("Buffers")]
    public Collider[] results = new Collider[64];
    private HashSet<Rigidbody> processedBodies = new HashSet<Rigidbody>();
    private HashSet<IDamageable> processedDamageables = new HashSet<IDamageable>();

    public void Explode()
    {
        int count = Physics.OverlapSphereNonAlloc(transform.position, radius, results, damageMask, QueryTriggerInteraction.Ignore);
        processedBodies.Clear();
        processedDamageables.Clear();

        for (int i = 0; i < count; i++)
        {
            Collider col = results[i];
            if (col.isTrigger) continue;

            Vector3 colliderCenter = col.bounds.center;
            if (Physics.Raycast(transform.position, colliderCenter - transform.position, (colliderCenter - transform.position).magnitude, obstacleMask))
                continue;

            float distance = Vector3.Distance(transform.position, col.ClosestPoint(transform.position));
            float falloff = Mathf.Clamp01(1 - (distance / radius));

            // Handle Damage
            IDamageable target = col.GetComponent<IDamageable>();
            if (target == null) target = col.GetComponentInParent<IDamageable>();

            if (target != null && !processedDamageables.Contains(target))
            {
                target.TakeDamage(maxDamage * falloff);
                processedDamageables.Add(target);
            }

            // Handle Physics
            Rigidbody rb = col.GetComponent<Rigidbody>();
            if (rb != null && !processedBodies.Contains(rb))
            {
                Vector3 dir = (colliderCenter - transform.position).normalized;
                Vector3 force = dir * explosionForce * falloff + Vector3.up * upwardsModifier * falloff;
                rb.AddExplosionForce(force, transform.position, radius);
                processedBodies.Add(rb);
            }
        }
    }
}
```

One common mistake is forgetting to clear your `HashSet` collections at the start of the `Explode` method, which would cause damage to stop applying after the first explosion!

