void UHitscanWeaponComponent::StartFire()
{
    float FireInterval = 60.0f / RoundsPerMinute;
    GetWorld()->GetTimerManager().SetTimer(FireTimerHandle, this, &UHitscanWeaponComponent::FireShot, FireInterval, true);
