void UHitscanWeaponComponent::FireShot()
{
    AActor* Owner = GetOwner();
    if (!Owner || !Owner->IsA(APawn::StaticClass())) return;

    APawn* OwnerPawn = Cast<APawn>(Owner);
    FVector EyesLocation;
    FRotator EyesRotation;

    if (OwnerPawn && OwnerPawn->GetViewLocation(EyesLocation))
    {
        EyesRotation = OwnerPawn->GetViewRotation();
        FVector ForwardVector = EyesRotation.Vector();

        // Apply Spread
        float SpreadRange = FMath::FRandRange(-SpreadDegrees, SpreadDegrees);
        FVector SpreadVector = FVector(FMath::FRandRange(-1.0f, 1.0f), FMath::FRandRange(-1.0f, 1.0f), FMath::FRandRange(-1.0f, 1.0f));
        FVector FinalDirection = (ForwardVector + (SpreadVector * (SpreadRange / 100.0f))).GetSafeNormal();

        FHitResult Hit;
        FCollisionQueryParams QueryParams;
        QueryParams.AddIgnoredActor(Owner);

        if (GetWorld()->LineTraceSingleByChannel(Hit, EyesLocation, EyesLocation + (FinalDirection * Range), ECC_Visibility, QueryParams))
        {
            if (AActor* HitActor = Hit.GetActor())
            {
                UDamageType* DamageType = DamageTypeClass ? DamageTypeClass.GetDefaultObject() : UDamageType::StaticClass().GetDefaultObject();

                float FinalDamage = Damage;
                FDamageEvent* DamageEvent = GetWorld()->MakeDamageEvent(DamageType, OwnerPawn->GetController(), Owner, FinalDamage, UDamageType::StaticClass());
                HitActor->TakeDamage(FinalDamage, DamageEvent, Owner, Hit.ImpactPoint);
            }
        }
    }
}
