#include "ProgressSaveSubsystem.h"
#include "Kismet/GameplayStatics.h"
#include "Async/Async.h"

void UProgressSaveSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
	Super::Initialize(Collection);
	LoadInitialSave();
}

void UProgressSaveSubsystem::LoadInitialSave()
{
	if (UProgressSaveGame* Loaded = Cast<UProgressSaveGame>(UGameplayStatics::LoadGameFromSlot(SaveSlot, 0)))
	{
		CurrentSave = Loaded;
	}
	else
	{
		CurrentSave = UProgressSaveGame::StaticLoadObject(UProgressSaveGame::StaticClass(), NULL, TEXT("ProgressSaveGame_Default"));
		if (!CurrentSave)
		{
			CurrentSave = NewObject<UProgressSaveGame>();
		}
	}
}

void UProgressSaveSubsystem::SaveNow()
{
	if (bIsSaving || !CurrentSave) return;

	bIsSaving = true;
	UProgressSaveGame* SaveCopy = CurrentSave; // Reference for async

	AsyncTask(ENamedThreads::AnyBackgroundThreadNormalTask, [this, SaveCopy]()
	{
		bool bSuccess = UGameplayStatics::SaveGameToSlot(SaveCopy, SaveSlot, 0);

		AsyncTask(ENamedThreads::GameThread, [this, bSuccess]()
		{
			bIsSaving = false;
			OnSaveCompleted.Broadcast(bSuccess);
		});
	});
}

