#include "Engine/AssetManager.h"

AWeaponPickup::AWeaponPickup()
{
    PrimaryActorTick.bCanEverTick = false;
    RootMesh = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("RootMesh"));
    RootComponent = RootMesh;
}

void AWeaponPickup::BeginPlay()
{
    Super::BeginPlay();
    LoadWeaponAssets();
}

void AWeaponPickup::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (LoadHandle.IsValid()) { LoadHandle->Cancel(); }
    Super::EndPlay(EndPlayReason);
}

void AWeaponPickup::LoadWeaponAssets()
{
    if (!WeaponData) return;
    if (LoadHandle.IsValid()) { LoadHandle->Cancel(); }

    FStreamableManager& Streamable = UAssetManager::GetStreamableManager();
    TArray<FSoftObjectPath> AssetsToLoad;

    if (WeaponData->Mesh.IsValid()) AssetsToLoad.Add(WeaponData->Mesh.ToSoftObjectPath());
    if (WeaponData->FireSound.IsValid()) AssetsToLoad.Add(WeaponData->FireSound.ToSoftObjectPath());

    LoadHandle = Streamable.RequestAsyncLoad(AssetsToLoad, FStreamableDelegate::CreateUObject(this, &AWeaponPickup::OnAssetsLoaded));
}

void AWeaponPickup::OnAssetsLoaded(TArray<FSoftObjectPath> Assets)
{
    if (WeaponData && WeaponData->Mesh.IsValid())
    {
        LoadedMeshComp = Cast<USkeletalMeshComponent>(RootMesh);
        LoadedMeshComp->SetSkeletalMesh(WeaponData->Mesh.Get());
    }
    if (WeaponData && WeaponData->FireSound.IsValid())
    {
        LoadedSound = WeaponData->FireSound.Get();
    }
}
