#include "InventoryComponent.h"
#include "Net/UnrealNetwork.h"

UInventoryComponent::UInventoryComponent() {
    SetIsReplicated(true);
}

void UInventoryComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const {
    Super::GetLifetimeReplicatedProps(OutLifetimeProps);
    DOREPLIFETIME(UInventoryComponent, Inventory);
}

int32 UInventoryComponent::AddItem(FName ItemId, int32 Amount) {
    if (!HasAuthority()) return -1;

    int32 CurrentCount = GetCount(ItemId);
    int32 NewCount = CurrentCount + Amount;

    for (auto& Entry : Inventory) {
        if (Entry.ItemId == ItemId) {
            Entry.Count = NewCount;
            break;
        }
    }

    if (NewCount > 0 && CurrentCount == 0) {
        Inventory.Add(FInventoryEntry(ItemId, NewCount));
    }

    OnItemCountChanged.Broadcast(ItemId, NewCount);
    BroadcastUpdate();
    return NewCount;
}

bool UInventoryComponent::RemoveItem(FName ItemId, int32 Amount) {
    if (!HasAuthority()) return false;

    int32 CurrentCount = GetCount(ItemId);
    if (CurrentCount < Amount) return false;

    int32 NewCount = CurrentCount - Amount;
    for (int32 i = 0; i < Inventory.Num(); ++i) {
        if (Inventory[i].ItemId == ItemId) {
            if (NewCount == 0) {
                Inventory.RemoveAt(i);
            } else {
                Inventory[i].Count = NewCount;
            }
            break;
        }
    }

    OnItemCountChanged.Broadcast(ItemId, NewCount);
    BroadcastUpdate();
    return true;
}

int32 UInventoryComponent::ServerUseItem(FName ItemId) {
    if (RemoveItem(ItemId, 1)) {
        return 0;
    }
    return -1;
}

int32 UInventoryComponent::GetCount(FName ItemId) const {
    for (const auto& Entry : Inventory) {
        if (Entry.ItemId == ItemId) return Entry.Count;
    }
    return 0;
}

void UInventoryComponent::OnRep_Inventory() {
    BroadcastUpdate();
}

void UInventoryComponent::BroadcastUpdate() {
    OnInventoryUpdated.Broadcast();
}
```

