**ProceduralTerrain.cpp**
```cpp
#include "ProceduralTerrain.h"
#include "Async/Async.h"
#include "Math/UnrealMath_Noise.h"

AProceduralTerrain::AProceduralTerrain() {
    State = ETerrainState::Idle;
}

void AProceduralTerrain::BeginPlay() {
    Super::BeginPlay();
}

void AProceduralTerrain::Generate(int32 Seed) {
    if (State == ETerrainState::Generating) return;

    State = ETerrainState::Generating;
    LatestSeed = Seed;

    // Capture data for the thread
    int32 CurrentSize = MapSize;
    float CurrentScale = HeightScale;

    AsyncTask(ENamedThreads::AnyBackgroundThreadNormalTask, [this, CurrentSize, CurrentScale, Seed]() {
        TArray<float> TempMap;
        TempMap.SetNum(CurrentSize * CurrentSize);

        // ParallelFor for noise generation
        ParallelFor(CurrentSize, [&](int32 Y) {
            for (int32 X = 0; X < CurrentSize; ++X) {
                float Noise = FMath::PerlinNoise1D(FMath::GridToWorldPosition(FVector2D(X, Y)).X * 0.01f); // Simplified for example
                // Note: For true 2D Perlin with Seed, use FMath::PerlinNoise2D or a custom seeded noise
                TempMap[Y * CurrentSize + X] = Noise * CurrentScale;
            }
        });

        // Check if actor is still valid before jumping back to Game Thread
        if (IsValid()) {
            AsyncTask(ENamedThreads::GameThread, [this, TempMap]() {
                if (!IsValid()) return;

                HeightMap = MoveTemp(TempMap);
                State = ETerrainState::Ready;
                OnTerrainReady.Broadcast();
            });
        }
    });
}

float AProceduralTerrain::GetHeightAt(int32 X, int32 Y) const {
    if (State != ETerrainState::Ready || X < 0 || Y < 0 || X >= MapSize || Y >= MapSize) {
        return 0.0f;
    }
    return HeightMap[Y * MapSize + X];
}
```

One common mistake to avoid is accessing `HeightMap` directly from the background thread; always ensure the final assignment happens on the Game Thread to prevent crashes!

