```csharp
using UnityEngine;
using Unity.Cinemachine;
using System;

public class CameraZone : MonoBehaviour
{
    public static event Action<CameraZone> ZoneEntered;

    [SerializeField] private CinemachineCamera zoneCamera;
    [SerializeField] private CinemachineImpulseSource impulseSource;

    [SerializeField] private int activePriority = 20;
    [SerializeField] private int inactivePriority = 10;

    private void Start()
    {
        if (zoneCamera != null)
            zoneCamera.Priority = inactivePriority;
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            if (zoneCamera != null)
            {
                zoneCamera.Priority = activePriority;
                ZoneEntered?.Invoke(this);
            }

            if (impulseSource != null)
            {
                impulseSource.GenerateImpulse();
            }
        }
    }

    private void OnTriggerExit(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            if (zoneCamera != null)
            {
                zoneCamera.Priority = inactivePriority;
            }
        }
    }
}
```

Make sure your Player object has a Rigidbody (set to `IsKinematic` if needed) so that the `OnTriggerEnter` events fire correctly.

