using UnityEngine;

public class EnemyAnimatorDriver : MonoBehaviour
{
    [SerializeField] private Animator animator;
    [SerializeField] private Rigidbody rb;
    [SerializeField] private float alertDistance = 10f;
    [SerializeField] private VoidEventChannel onHit;

    private Transform playerTransform;
    private int speedHash;
    private int alertHash;
    private int hitHash;

    private void Awake()
    {
        speedHash = Animator.StringToHash("Speed");
        alertHash = Animator.StringToHash("Alert");
        hitHash = Animator.StringToHash("Hit");
    }

    private void Start()
    {
        // Using the modern GameObject.FindObjectOfType approach
        var player = GameObject.FindObjectOfType<PlayerMarker>();
        if (player != null) playerTransform = player.transform;
    }

    private void OnEnable() => onHit.OnEventRaised += () => animator.SetTrigger(hitHash);
    private void OnDisable() => onHit.OnEventRaised -= () => animator.SetTrigger(hitHash);

    private void Update()
    {
        float horizontalSpeed = Mathf.Abs(rb.velocity.x) + Mathf.Abs(rb.velocity.z);
        animator.SetFloat(speedHash, Mathf.Lerp(animator.GetFloat(speedHash), horizontalSpeed, Time.deltaTime * 10f));

        bool isAlert = playerTransform != null && Vector3.Distance(transform.position, playerTransform.position) < alertDistance;
        animator.SetBool(alertHash, isAlert);
    }
}
